"/us/en/surgical-technologies/services/instruments/new-accounts": {"template":"long-page-detail","metadata":{"title":"New accounts","pageTitle":null,"description":"Connect with customer service and MDM teams to make changes to your account and request new account. New account forms available by request. Add a ship too address, change a Biller or Payer for the account. Including adding 3rd party Payers like Trimedx and GE. Fill out email for below, you will receive a new/change account request form. Fill this out and reply with it to submit your change. You will be connected with a customer service team member. To help support you through the process. ","image":null,"imageAlt":null,"tags":["stryker:content-type/hcp_content","stryker:custom/instruments/new-accounts/customer-service","stryker:custom/instruments/new-accounts/new-account","stryker:custom/instruments/new-accounts/account-changes","stryker:custom/instruments/new-accounts/biller","stryker:custom/instruments/new-accounts/payer","stryker:custom/instruments/new-accounts/ship-too","stryker:custom/instruments/new-accounts/address","stryker:custom/instruments/new-accounts/account-name-change","stryker:custom/instruments/new-accounts/add-a-3rd-party-provider","stryker:custom/instruments/new-accounts/trimedx","stryker:custom/instruments/new-accounts/ge","stryker:custom/instruments/new-accounts/contact-email","stryker:custom/instruments/new-accounts/change-request"],"originallyPublished":null,"lastPublished":"2021-05-03T14:19:50.000Z","contentID":"D0000071450 Rev. AA"},"anchors":[],"disclaimer":null,"forms":[{"formId":"1566","afterSubmitAction":"showMessage","message":"Thank you!","useProduction":true}],"tabs":[],"cardLists":[],"missingAlt":[]},
